// Ported 2026-11-20 from WPI-HPRC/pid-tuner include/PidController.h (branch
// feat/serial-pid-tuner, commit d7b3440). Canards-Rocket carries the same code
// in src/canards/pid_tuner/PidController.h.
//
// The logic must stay IDENTICAL to pid-tuner, so that servo gains tuned on the
// bench with the tuner stay valid in flight. Only the two #include paths differ
// from the original; the tuner's own formatting is kept so the files can be
// diffed. Do not edit this file on its own: change the tuner, then copy again.
#pragma once

#include "ServoControl/ControlMath.h"
#include "ServoControl/RunningExpAverage.h"

namespace tuning {

struct PidTerms {
    float proportional = 0;
    float integral = 0;
    float derivative = 0;
    float output = 0;
};

/** Position correction in degrees, with seconds as the time unit. */
class PidController {
  public:
    const PidTerms &getTerms() const { return terms; }
    float getIntegralState() const { return ki > 0 ? integralTerm / ki : 0; }

    void reset() {
        integralTerm = 0;
        lastMeasurement = 0;
        terms = {};
        initialized = false;
        derivativeFilter = RunningExpAverage<float>(DerivativeFilterAlpha);
    }

    bool setGains(float proportionalGain, float integralGain,
                  float derivativeGain) {
        if (!isValidGain(proportionalGain) || !isValidGain(integralGain) ||
            !isValidGain(derivativeGain)) {
            return false;
        }
        kp = proportionalGain;
        ki = integralGain;
        kd = derivativeGain;
        reset();
        return true;
    }

    float update(float target, float measured, float elapsedSeconds,
                 float minOutput, float maxOutput) {
        if (!std::isfinite(target) || !std::isfinite(measured) ||
            !std::isfinite(elapsedSeconds) || elapsedSeconds <= 0 ||
            elapsedSeconds > 0.1f) {
            return terms.output;
        }

        float error = target - measured;
        // Differentiate the measurement so target steps do not create a kick.
        float measurementDerivative =
            initialized ? -(measured - lastMeasurement) / elapsedSeconds : 0;
        derivativeFilter.update(measurementDerivative);
        lastMeasurement = measured;
        initialized = true;
        terms.proportional = kp * error;
        terms.derivative = kd * derivativeFilter.getAvg();

        float candidateIntegral = clamp(
            integralTerm + ki * error * elapsedSeconds, minOutput, maxOutput);
        float candidateOutput =
            terms.proportional + candidateIntegral + terms.derivative;
        bool withinLimits =
            candidateOutput >= minOutput && candidateOutput <= maxOutput;
        bool unwindingHighLimit = candidateOutput > maxOutput && error < 0;
        bool unwindingLowLimit = candidateOutput < minOutput && error > 0;
        if (withinLimits || unwindingHighLimit || unwindingLowLimit) {
            integralTerm = candidateIntegral;
        }

        terms.integral = integralTerm;
        terms.output =
            clamp(terms.proportional + terms.integral + terms.derivative,
                  minOutput, maxOutput);
        return terms.output;
    }

  private:
    static constexpr float DerivativeFilterAlpha = 0.2f;
    float kp = 0;
    float ki = 0;
    float kd = 0;
    float lastMeasurement = 0;
    float integralTerm = 0;
    bool initialized = false;
    RunningExpAverage<float> derivativeFilter{DerivativeFilterAlpha};
    PidTerms terms;

    static bool isValidGain(float gain) {
        return std::isfinite(gain) && gain >= 0 && gain <= 10000;
    }
};

} // namespace tuning
